sksl:
uniform shader image;
uniform float2 size;
uniform float time;
layout(color) uniform half4 key;
uniform float tolerance;
uniform float softness;
uniform float invert;
uniform float defringe;
uniform float luma;
uniform float style;
float2 chroma(half3 c) { return float2(-0.1687 * c.r - 0.3313 * c.g + 0.5 * c.b, 0.5 * c.r - 0.4187 * c.g - 0.0813 * c.b); }
float3 yuv(float3 c) {
    float y = dot(c, float3(0.299, 0.587, 0.114));
    return float3(y, 0.492 * (c.b - y), 0.877 * (c.r - y));
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float keep;
    if (style > 0.5) {
        if (key.a <= 0.0) return c;
        float3 e = yuv(float3(unpremul(c).rgb)) - yuv(float3(key.rgb));
        float d = length(float3(luma * e.x, e.yz));
        keep = clamp((d - tolerance + softness) / max(softness, 0.0001), 0.0, 1.0);
    } else {
        float d = distance(chroma(unpremul(c).rgb), chroma(key.rgb));
        keep = smoothstep(tolerance, tolerance + softness + 0.0001, d);
    }
    float k = invert > 0.5 ? 1.0 - keep : keep;
    if (defringe > 0.5 && k > 0.0 && k < 1.0 && c.a > 0.0) {
        return half4(c.rgb * half(k * k), c.a * half(k));
    }
    return c * half(k);
}
